def sieve_count(n: int) -> int:
    if n <= 2:
        return 0
    if n == 3:
        return 1
    size = n // 2
    sieve = bytearray([1]) * size
    sieve[0] = 0
    limit = math.isqrt(n - 1) // 2
    for i in range(1, limit + 1):
        if sieve[i]:
            p = 2 * i + 1
            start = (p * p) // 2
            sieve[start::p] = bytearray((size - start - 1) // p + 1)
    return sieve.count(1) + 1

